// Dựng body gọi Gemini từ TEXT nhân viên gửi qua Telegram
const tg = $('Telegram: nhận phiếu').item.json;
const msg = tg.message || {};
const noiDung = (msg.text || msg.caption || '').trim();
const prompt = "Bạn là trợ lý kế toán nhà máy xay xát gạo Thạnh Hương. Nhân viên GÕ TEXT mô tả một chứng từ/phiếu (mua lúa, bán cám/trấu/gạo, công nợ...) bằng tiếng Việt tự nhiên, có thể viết tắt. Hãy hiểu và tách thành các trường.\n\nCHỈ TRẢ VỀ 1 object JSON đúng cấu trúc (không giải thích):\n{\n  \"ngay\": \"ngày, dạng DD/MM/YYYY; nếu không ghi thì để rỗng\",\n  \"so_phieu\": \"số phiếu/chứng từ nếu có\",\n  \"nguoi_ban_khach_hang\": \"tên người bán/khách hàng/nhà cung cấp\",\n  \"loai_hang_lua\": \"loại hàng/lúa (lúa tươi, OM5451, cám gạo, trấu, tấm...)\",\n  \"so_xe\": \"biển số xe nếu có\",\n  \"tl_xe_vao\": \"kg xe vào nếu có, CHỈ số\",\n  \"tl_xe_ra\": \"kg xe ra nếu có, CHỈ số\",\n  \"tl_hang\": \"kg hàng (khối lượng chính), CHỈ số\",\n  \"do_am\": \"độ ẩm % nếu có\",\n  \"kieu_can\": \"NHẬP hay XUẤT\",\n  \"ghi_chu_chat_luong\": \"đơn giá, thành tiền, chất lượng, ghi chú khác nếu có\",\n  \"nguoi_can\": \"tên người ghi/nộp nếu có\",\n  \"do_tin_cay\": \"cao | trung bình | thấp\",\n  \"can_kiem_tra\": true hoặc false (true nếu thiếu/không chắc trường quan trọng),\n  \"ly_do_kiem_tra\": \"lý do, rỗng nếu không\"\n}\nTrường không có để rỗng. Số kg chỉ ghi con số, bỏ 'kg' và dấu phẩy ngăn nghìn." + '\n\nNỘI DUNG NHÂN VIÊN GỬI:\n"""' + noiDung + '"""';
return { json: {
  chatId: (msg.chat && msg.chat.id) || '',
  messageId: msg.message_id || '',
  noiDung,
  body: { contents: [{ parts: [{ text: prompt }] }], generationConfig: { temperature: 0, response_mime_type: 'application/json' } }
} };

// Phân tích JSON Gemini + kiểm tra logic số cân
const prep = $('Chuẩn bị yêu cầu (Gemini)').item.json;
const linkAnh = 'telegram-msg-' + (prep.messageId || '');
let text = '';
try { text = $json.candidates[0].content.parts[0].text; } catch (e) { text = ''; }
let clean = (text || '').trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
let data = {}; let parseError = '';
try { data = JSON.parse(clean); } catch (e) { parseError = 'Không đọc được JSON từ AI'; data = {}; }

const toNum = (s) => { if (s === null || s === undefined || s === '') return null; const n = Number(String(s).replace(/[^0-9.\-]/g, '')); return isNaN(n) ? null : n; };
const vao = toNum(data.tl_xe_vao), ra = toNum(data.tl_xe_ra); let hang = toNum(data.tl_hang);
if (hang === null && vao !== null && ra !== null) hang = Math.abs(vao - ra);

let mathOk = true, mathNote = '';
if (vao !== null && ra !== null && hang !== null) {
  const diff = Math.abs(Math.abs(vao - ra) - hang);
  if (diff > Math.max(20, hang * 0.01)) { mathOk = false; mathNote = 'Lệch cân: |'+vao+'-'+ra+'| khác '+hang; }
}

const conf = String(data.do_tin_cay || '').toLowerCase();
const lowConf = conf.includes('thấp') || conf.includes('thap') || conf === 'low';
const aiFlag = data.can_kiem_tra === true || data.can_kiem_tra === 'true';
const needsReview = !!(parseError || lowConf || !mathOk || aiFlag);

const reasons = [];
if (parseError) reasons.push(parseError);
if (lowConf) reasons.push('AI báo độ tin cậy thấp');
if (!mathOk) reasons.push(mathNote);
if (aiFlag && data.ly_do_kiem_tra) reasons.push(data.ly_do_kiem_tra);
else if (aiFlag) reasons.push('AI đánh dấu cần kiểm tra');

return { json: {
  'Thời gian xử lý': new Date().toISOString(),
  'Tên file': 'Telegram text',
  'Link ảnh': linkAnh,
  'Ngày phiếu': data.ngay || '',
  'Số phiếu': data.so_phieu || '',
  'Người bán / Khách hàng': data.nguoi_ban_khach_hang || '',
  'Loại hàng / lúa': data.loai_hang_lua || '',
  'Số xe': data.so_xe || '',
  'TL xe vào (kg)': vao !== null ? vao : '',
  'TL xe ra (kg)': ra !== null ? ra : '',
  'TL hàng (kg)': hang !== null ? hang : '',
  'Độ ẩm (%)': data.do_am || '',
  'Kiểu cân': data.kieu_can || '',
  'Ghi chú chất lượng': data.ghi_chu_chat_luong || '',
  'Người cân': data.nguoi_can || '',
  'Độ tin cậy': data.do_tin_cay || '',
  'Cần kiểm tra': needsReview ? 'CÓ' : 'Không',
  'Lý do kiểm tra': reasons.join('; ')
} };

